def find_interior_layers(grid):
    """Find how many 'layers' from the outside each cell is"""

    # First pass: mark boundary cells
    visited = set()

    # Queue for BFS from outside
    queue = []

    for r in range(7):
        for c in range(7):
            if not (grid[r][c] == 8):
                queue.append((r,c))
            else:
                visited.add((r,c))

    # Actually do BFS from outside to find distance to non-8
    dist_to_empty = {}

    for r in range(7):
        for c in range(7):
            dist_to_empty[(r,c)] = float('inf')

    # Initialize BFS queue with all empty cells
    queue = [(r,c) for r in range(7) for c in range(7) if grid[r][c] != 8]

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 7 and 0 <= nc < 7:
                new_dist = dist_to_empty[(r,c)] + 1
                if new_dist < dist_to_empty.get((nr,nc), float('inf')):
                    dist_to_empty[(nr,nc)] = new_dist

    return dist_to_empty

