def min_dist_to_bbox_edge(r, c, grids_in):
    """Minimum Manhattan distance to any edge of bounding box"""
    min_r, max_r = 7, -1
    min_c, max_c = 7, -1

    for rr in range(7):
        for cc in range(7):
            if grids_in[rr][cc] == 8:
                min_r = min(min_r, rr)
                max_r = max(max_r, rr)
                min_c = min(min_c, cc)
                max_c = max(max_c, cc)

    # Compute absolute distances
    dist_top = r - min_r
    dist_bottom = max_r - r
    dist_left = c - min_c
    dist_right = max_c - c

    return min(dist_top, dist_bottom, dist_left, dist_right)

