def dist_to_corner(r, c, grids_in):
    """Compute distances to all four bbox corners"""
    min_r, max_r = 7, -1
    min_c, max_c = 7, -1

    for rr in range(7):
        for cc in range(7):
            if grids_in[rr][cc] == 8:
                min_r = min(min_r, rr)
                max_r = max(max_r, rr)
                min_c = min(min_c, cc)
                max_c = max(max_c, cc)

    # Distances in Manhattan or Euclidean
    tl = abs((r-min_r) - 0) + abs((c-min_c) - 0)
    tr = abs((r-min_r) - 0) + abs((c-min_c) - (max_c-min_c))
    bl = abs((r-min_r) - (max_r-min_r)) + abs((c-min_c) - 0)
    br = abs((r-min_r) - (max_r-min_r)) + abs((c-min_c) - (max_c-min_c))

    return {
        "TL": tl,
        "TR": tr,
        "BL": bl,
        "BR": br
    }

