    # Left side
    elif r <= 1 and c >= 0:
        return 3  # Top-left area
    elif r >= 2 and c <= 1:
        return 2  # Lower left area
    elif r == 1 and c <= 1:
        return 3

    # Middle columns
    elif r <= 1:
        return 1  # Upper middle
    elif r >= 2 and c <= 3:
        return 1 or 2  # Need refinement

    return 1  # Default

