def predict_two_modes(r, c, grids_in):
    """Predict: detect mode from bbox, then apply appropriate rules"""

    min_r = max_r = -1
    min_c = max_c = -1

    for rr in range(7):
        for cc in range(7):
            if grids_in[rr][cc] == 8:
                min_r = min(min_r if min_r != -1 else rr, rr)
                max_r = max(max_r if max_r != -1 else rr, rr)
                min_c = min(min_c if min_c != -1 else cc, cc)
                max_c = max(max_c if max_c != -1 else cc, cc)

    h = max_r - min_r + 1
    w = max_c - min_c + 1
    rel_r = r - min_r

    # Determine mode
    # Mode A (like Demo1): h=5, values shift differently
    # Mode B (like Demo2): h=6, values shift differently

    # Key difference: where does the value change happen?
    # In Demo1, col 4 changes 4→1 at row 3; in Demo2, at row 2
    # Threshold might be related to w or absolute height

    # Use width or absolute size as indicator
    if w >= 6:  # Wide shape → Mode A
        mode = 'A'
    else:  # Narrower shape → Mode B
        mode = 'B'

    print(f"Mode {mode}: h={h}, w={w}")

    # RIGHT SIDE (cols >= 4)
    if c >= 4:
        if mode == 'A':
            # Rows 1-2 get 4 (relative row < 3)
            threshold = 3
        else:
            # Rows 0-1 get 4 (relative row < 2)
            threshold = 2

        if rel_r < threshold:
            return 4
        else:
            return 1

    # LEFT SIDE (cols <= 1)
    elif c <= 1:
        if mode == 'A':
            # Rows 1-2 get 3, row 3+ get 2
            if rel_r <= 2:
                return 3
            else:
                return 2
        else:
            # Rows 0-1 get 2, rows 2+ get 1
            if rel_r <= 1:
                return 2
            else:
                return 1

    # MIDDLE COLUMNS
    elif c == 2:
        if mode == 'A':
            if rel_r <= 1:
                return 1
            else:
                return 2
        else:
            if rel_r <= 2:
                return 1
            else:
                return 3

    elif c == 3:
        return 1

    return 1

